package org.fribok.bookkeeping.service.year;
import se.swedsoft.bookkeeping.data.*; import se.swedsoft.bookkeeping.data.system.SSDB; import java.time.LocalDate; import java.util.List;
/** Accounting year creation service. */
public final class AccountingYearService {private final SSDB db;public AccountingYearService(SSDB d){db=d;}public List<SSAccountPlan> accountPlans(){return db.getAccountPlans();}public SSNewAccountingYear create(LocalDate f,LocalDate t,SSAccountPlan p){if(f==null||t==null||t.isBefore(f))throw new IllegalArgumentException("Accounting year dates are invalid");if(p==null)throw new IllegalArgumentException("Account plan is required");boolean overlap=db.getYears().stream().anyMatch(y->!t.isBefore(y.getLocalFrom())&&!f.isAfter(y.getLocalTo()));if(overlap)throw new IllegalArgumentException("Accounting year overlaps an existing year");SSNewAccountingYear y=new SSNewAccountingYear();y.setLocalFrom(f);y.setLocalTo(t);y.setAccountPlan(new SSAccountPlan(p,true));db.addAccountingYear(y);return y;}}
